package main

import (
    "fmt"
    "os"
    "os/exec"
)

// Test-only adapter for this elevated Windows runner. Chrome otherwise
// de-elevates by relaunching, losing the stdout handle used by --dump-dom.
// Every existing argument and all output/exit results pass through unchanged.
func main() {
    args := append([]string{"--do-not-de-elevate"}, os.Args[1:]...)
    cmd := exec.Command(`C:\Program Files\Google\Chrome\Application\chrome.exe`, args...)
    cmd.Stdin, cmd.Stdout, cmd.Stderr = os.Stdin, os.Stdout, os.Stderr
    if err := cmd.Run(); err != nil {
        if exit, ok := err.(*exec.ExitError); ok { os.Exit(exit.ExitCode()) }
        fmt.Fprintln(os.Stderr, err)
        os.Exit(1)
    }
}
